const icons={食物:'🍜',交通:'🚇',日常:'☀️',娛樂:'🎬',住居:'⌂',醫療:'✚',薪資:'✦',其他:'◦'};
const initial={accounts:[{id:1,name:'日常銀行帳戶',type:'銀行帳戶',balance:28640},{id:2,name:'現金錢包',type:'現金',balance:1250},{id:3,name:'玉山信用卡',type:'信用卡',balance:-4620}],transactions:[{id:1,date:'2026-10-29',desc:'公司附近午餐',category:'食物',account:'日常銀行帳戶',amount:180,type:'expense'},{id:2,date:'2026-10-28',desc:'捷運往返台北',category:'交通',account:'悠遊卡',amount:60,type:'expense'},{id:3,date:'2026-10-28',desc:'十月薪資',category:'薪資',account:'日常銀行帳戶',amount:52000,type:'income'},{id:4,date:'2026-10-27',desc:'串流影集',category:'娛樂',account:'玉山信用卡',amount:390,type:'expense'},{id:5,date:'2026-10-26',desc:'超市採買',category:'日常',account:'日常銀行帳戶',amount:735,type:'expense'},{id:6,date:'2026-10-25',desc:'咖啡與早餐',category:'食物',account:'現金錢包',amount:145,type:'expense'}],budgets:[{category:'食物',limit:6000},{category:'交通',limit:2000},{category:'日常',limit:5000},{category:'娛樂',limit:2500}],subscriptions:[{id:1,name:'Netflix',amount:390,cycle:'每月',next:'2026-11-03',account:'玉山信用卡',status:'啟用中'},{id:2,name:'iCloud+',amount:90,cycle:'每月',next:'2026-11-08',account:'日常銀行帳戶',status:'啟用中'},{id:3,name:'Spotify',amount:149,cycle:'每月',next:'2026-11-12',account:'玉山信用卡',status:'啟用中'}]};
let state=JSON.parse(localStorage.getItem('pocketflow-v1')||'null')||initial, currentForm='';const money=n=>new Intl.NumberFormat('zh-TW',{style:'currency',currency:'TWD',maximumFractionDigits:0}).format(n);const saveState=()=>localStorage.setItem('pocketflow-v1',JSON.stringify(state));const expense=()=>state.transactions.filter(t=>t.type==='expense').reduce((a,t)=>a+t.amount,0);const income=()=>state.transactions.filter(t=>t.type==='income').reduce((a,t)=>a+t.amount,0);const byCat=()=>state.transactions.filter(t=>t.type==='expense').reduce((o,t)=>(o[t.category]=(o[t.category]||0)+t.amount,o),{});
function go(page){document.querySelectorAll('.page').forEach(e=>e.classList.remove('active'));document.querySelectorAll('.nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===page));document.getElementById(page).classList.add('active');render()}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));
function render(){renderDashboard();renderTransactions();renderBudgets();renderSubscriptions();renderAccounts();enhanceSelects()}
function renderDashboard(){let e=expense(),i=income(),b=byCat(),remaining=state.budgets.reduce((sum,x)=>sum+x.limit,0)-e;document.getElementById('kpis').innerHTML=`<div class="card feature"><div class="label">本月總支出</div><div class="amount">${money(e)}</div><div class="hint">較上月少 8.4%</div></div><div class="card"><div class="label">本月收入</div><div class="amount">${money(i)}</div><div class="hint positive">收支流入穩定</div></div><div class="card"><div class="label">淨現金流</div><div class="amount">${money(i-e)}</div><div class="hint positive">本月有盈餘</div></div><div class="card"><div class="label">剩餘預算</div><div class="amount">${money(remaining)}</div><div class="hint">4 個分類已設定</div></div>`;let days=['23','24','25','26','27','28','29'],vals=[190,420,145,735,390,60,180],max=Math.max(...vals);document.getElementById('chart').innerHTML=days.map((d,n)=>`<div class="bar-wrap"><div class="bar" style="height:${vals[n]/max*130}px"></div>${d} 日</div>`).join('');document.getElementById('categories').innerHTML=Object.entries(b).sort((a,b)=>b[1]-a[1]).map(([c,a])=>`<div class="cat-row"><div class="badge">${icons[c]||'◦'}</div><div><strong>${c}</strong><div class="progress"><i style="width:${Math.min(100,a/e*100)}%"></i></div></div><strong>${money(a)}</strong></div>`).join('');document.getElementById('budgetPreview').innerHTML=state.budgets.map(x=>{let used=b[x.category]||0,p=used/x.limit*100;return `<div><div class="section-head" style="margin:0"><strong>${x.category}</strong><span class="hint">${money(used)} / ${money(x.limit)}</span></div><div class="progress ${p>=80?'warn':''}"><i style="width:${Math.min(p,100)}%"></i></div></div>`}).join('');document.getElementById('recent').innerHTML=state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(t=>`<div class="transaction"><div class="badge">${icons[t.category]||'◦'}</div><div><strong>${t.desc}</strong><small>${t.date} · ${t.category}</small></div><strong class="${t.type==='income'?'positive':''}">${t.type==='income'?'+':'-'}${money(t.amount)}</strong></div>`).join('')}
function renderTransactions(){let q=(document.getElementById('search')?.value||'').toLowerCase(),f=document.getElementById('filterType')?.value||'';let list=state.transactions.filter(t=>(!q||`${t.desc}${t.category}`.toLowerCase().includes(q))&&(!f||t.type===f)).sort((a,b)=>b.date.localeCompare(a.date));document.getElementById('transactionCount').textContent=`${list.length} 筆紀錄 · 依日期整理`;let days={};list.forEach(t=>(days[t.date]??=[]).push(t));document.getElementById('transactionRows').innerHTML=Object.entries(days).map(([date,items])=>{let spent=items.filter(x=>x.type==='expense').reduce((n,x)=>n+x.amount,0),earned=items.filter(x=>x.type==='income').reduce((n,x)=>n+x.amount,0),summary=`支出 ${money(spent)}${earned?` · 收入 ${money(earned)}`:''}`;return `<tr class="day-group"><td colspan="5"><div class="day-heading"><strong>${date} · ${date==='2026-10-29'?'今天':''}</strong><span>${summary}</span></div></td></tr>`+items.map(t=>`<tr><td></td><td><strong>${t.desc}</strong></td><td>${t.account}</td><td><span class="type ${t.type==='income'?'income':''}">${t.category}</span></td><td class="${t.type==='income'?'positive':''}"><strong>${t.type==='income'?'+':'-'}${money(t.amount)}</strong></td></tr>`).join('')}).join('')||'<tr><td colspan="5" class="empty">找不到符合的交易</td></tr>'}
function renderBudgets(){let b=byCat();document.getElementById('budgetList').innerHTML=state.budgets.map(x=>{let used=b[x.category]||0,p=used/x.limit*100;return `<article class="budget-item"><header><strong>${icons[x.category]||'◦'}　${x.category}</strong><strong class="${p>100?'negative':p>=80?'':'positive'}">${Math.round(p)}%</strong></header><p>已使用 ${money(used)}，預算上限 ${money(x.limit)}</p><div class="progress ${p>=80?'warn':''}"><i style="width:${Math.min(p,100)}%"></i></div></article>`}).join('')||'<div class="empty">尚未設定預算</div>'}
function renderSubscriptions(){let total=state.subscriptions.filter(s=>s.status==='啟用中').reduce((a,s)=>a+s.amount,0);document.getElementById('subscriptionKpis').innerHTML=`<div class="card feature"><div class="label">平均月成本</div><div class="amount">${money(total)}</div><div class="hint">${state.subscriptions.filter(s=>s.status==='啟用中').length} 個啟用中的訂閱</div></div><div class="card"><div class="label">下一筆扣款</div><div class="amount">11/03</div><div class="hint">Netflix · ${money(390)}</div></div>`;document.getElementById('subscriptionList').innerHTML=state.subscriptions.map(s=>`<article class="sub-item"><header><div><strong>${s.name}</strong><p>${s.cycle} · ${s.account}</p></div><div style="text-align:right"><strong>${money(s.amount)}</strong><p>${s.status}</p></div></header><div class="hint">下次扣款：${s.next}</div></article>`).join('')||'<div class="empty">還沒有訂閱項目</div>'}
function renderAccounts(){document.getElementById('accountGrid').innerHTML=state.accounts.map(a=>`<article class="account"><div class="icon">${a.type==='信用卡'?'▣':a.type==='現金'?'◫':'◇'}</div><h3>${a.name}</h3><div class="hint">${a.type}</div><div class="amount" style="font-size:22px">${money(a.balance)}</div></article>`).join('')}
function openModal(kind,preset={}){currentForm=kind;let title={transaction:'新增交易',budget:'設定分類預算',subscription:'新增訂閱',account:'新增帳戶'}[kind],fields={transaction:`<label>類型<select name="type"><option value="expense">支出</option><option value="income">收入</option></select></label><label>金額<input name="amount" type="number" min="1" required placeholder="例如 180"></label><label>分類<select name="category">${['食物','交通','日常','娛樂','住居','醫療','其他','薪資'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>帳戶<select name="account">${state.accounts.map(a=>`<option>${a.name}</option>`).join('')}</select></label><label>日期<input name="date" type="date" value="2026-10-29" required></label><label class="wide">描述<input name="desc" maxlength="500" required placeholder="例：公司附近午餐"></label>`,budget:`<label>分類<select name="category">${['食物','交通','日常','娛樂','住居','醫療','其他'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>本月預算<input name="limit" type="number" min="1" required placeholder="例如 6000"></label>`,subscription:`<label>服務名稱<input name="name" required placeholder="例如 Netflix"></label><label>每期金額<input name="amount" type="number" min="1" required></label><label>計費週期<select name="cycle"><option>每月</option><option>每年</option><option>每週</option></select></label><label>付款帳戶<select name="account">${state.accounts.map(a=>`<option>${a.name}</option>`).join('')}</select></label><label>下次扣款日<input name="next" type="date" value="2026-11-01" required></label>`,account:`<label>帳戶名稱<input name="name" required placeholder="例如 日常銀行帳戶"></label><label>帳戶類型<select name="type"><option>銀行帳戶</option><option>現金</option><option>信用卡</option><option>電子支付</option></select></label><label class="wide">起始餘額<input name="balance" type="number" value="0" required></label>`}[kind];document.getElementById('modalTitle').textContent=title;document.getElementById('formFields').innerHTML=fields;document.getElementById('formActions').innerHTML=kind==='transaction'?'<button class="secondary keep-adding" type="submit" data-more="true">儲存並再記一筆</button><button class="primary" type="submit">儲存</button>':'<button class="primary" type="submit">儲存</button>';Object.entries(preset).forEach(([key,value])=>{let field=document.querySelector(`#form [name="${key}"]`);if(field)field.value=value});enhanceSelects();document.getElementById('modal').classList.add('open')}
function enhanceSelects(){document.querySelectorAll('select:not([data-enhanced])').forEach(select=>{select.dataset.enhanced='true';select.classList.add('enhanced-native');let wrap=document.createElement('div');wrap.className='custom-select';let trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';let menu=document.createElement('div');menu.className='select-menu';menu.setAttribute('role','listbox');const refresh=()=>{trigger.textContent=select.options[select.selectedIndex]?.text||'請選擇';menu.querySelectorAll('.select-option').forEach((item,i)=>item.classList.toggle('selected',i===select.selectedIndex))};Array.from(select.options).forEach((option,index)=>{let item=document.createElement('button');item.type='button';item.className='select-option';item.textContent=option.text;item.setAttribute('role','option');item.onclick=()=>{select.selectedIndex=index;select.dispatchEvent(new Event('change',{bubbles:true}));refresh();wrap.classList.remove('open')};menu.append(item)});trigger.onclick=()=>{document.querySelectorAll('.custom-select.open').forEach(x=>{if(x!==wrap)x.classList.remove('open')});wrap.classList.toggle('open')};select.after(wrap);wrap.append(trigger,menu);select.addEventListener('change',refresh);refresh()})}
document.addEventListener('click',event=>{if(!event.target.closest('.custom-select'))document.querySelectorAll('.custom-select.open').forEach(x=>x.classList.remove('open'))});
function closeModal(){document.getElementById('modal').classList.remove('open')}function save(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),keepAdding=e.submitter?.dataset.more==='true';if(currentForm==='transaction'){d.id=Date.now();d.amount=Number(d.amount);state.transactions.unshift(d)}if(currentForm==='budget'){d.limit=Number(d.limit);let old=state.budgets.find(x=>x.category===d.category);old?old.limit=d.limit:state.budgets.push(d)}if(currentForm==='subscription'){d.id=Date.now();d.amount=Number(d.amount);d.status='啟用中';state.subscriptions.push(d)}if(currentForm==='account'){d.id=Date.now();d.balance=Number(d.balance);state.accounts.push(d)}saveState();closeModal();render();toast('已儲存到本機資料');if(keepAdding&&currentForm==='transaction')openModal('transaction',{type:d.type,account:d.account,date:d.date})}
function toast(msg){let e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}function exportCSV(){let rows=[['日期','類型','描述','分類','帳戶','金額'],...state.transactions.map(t=>[t.date,t.type,t.desc,t.category,t.account,t.amount])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='pocketflow-transactions.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV 已下載')};render();

